import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Muestra_Cards } from '../../../Redux/Actions/Usuario/Action-user';

import './ZatosCards.css'
import ZapatosCard from './Zapatos_Card';


const ZapatosCards = ({ cards }) => {
  const dispatch = useDispatch();
  const cardss = useSelector((state) => state.CARDS) || [];

  useEffect(() => {
    dispatch(Muestra_Cards());
  }, [dispatch]);

  

  return (
    <div className="zapatos-cards">
      {cards.map((card) => (
        <ZapatosCard key={card.id} data={card} />
      ))}
    </div>
  );
};

export default ZapatosCards;
